fn solve(x: i32) -> i32 {
    // d is the repeated digit; k is the length (1..4)
    let d = x % 10;

    let mut k = 0;
    let mut t = x;
    while t > 0 {
        k += 1;
        t /= 10;
    }

    let prev_digits_cost = (d - 1) * 10;           // (1+2+3+4) per digit
    let up_to_k_cost = k * (k + 1) / 2;            // 1+2+...+k

    prev_digits_cost + up_to_k_cost
}

